import React from "react";

/**
 * 
 * Component for the Work Items View for Mobile.
 * 
 * @param {Object} props
 * 
 * @param {boolean} props.scrollElementIsVisible
 * 
 * @param {string} props.projectName
 * @param {string} props.projectDescriptionMob
 * @param {string} props.projectImageMob
 * @param {string} props.projectImageMobAlt
 * @param {Array} props.projectCTAs
 * @param {Object} props.projectCTAs[index]
 * @param {string} props.projectCTAs[index].link
 * @param {string} props.projectCTAs[index].text
 * 
 * @param {ReactRef} ref
 */

const HomeMobileWorkItem = React.forwardRef(({ scrollElementIsVisible, projectName, projectDescriptionMob, projectCTAs, projectImageMob, projectImageMobAlt }, ref) => {
    return (
        <div className={`my-work-item flipInXInitial ${scrollElementIsVisible ? 'flipInX animated slow' : ''}`} ref={ref}>
            <div className="my-work-item-image-container">
                <img src={projectImageMob} alt={projectImageMobAlt} />
            </div>
            <div className="my-work-item-desc">
                <div>{projectName}</div>
                <div className="my-work-item-inner-desc">{projectDescriptionMob}</div>

                {projectCTAs.map((cta, index) => (
                    <a
                        key={`HomeMobileWorkItem-${projectName}-cta-${index}`}
                        className="my-work-item-inner-link"
                        href={cta.link}
                        target="_blank"
                        rel="noopener noreferrer"
                    >
                        {cta.text}
                    </a>
                ))}
            </div>
        </div>
    )
})

export default HomeMobileWorkItem;
