import React from "react";

/**
 * 
 * Component for the Work Items View for Desktop.
 * 
 * @param {Object} props
 * @param {string} props.projectName
 * @param {string} props.projectDescription
 * @param {Array} props.projectCTAs
 * @param {Object} props.projectCTAs[index]
 * @param {string} props.projectCTAs[index].link
 * @param {string} props.projectCTAs[index].text
 */
export default function HomeDesktopWorkItem({ projectName, projectDescription, projectCTAs, projectImage }) {
    return (
        <div className="desktop-my-work-item-background" style={{backgroundImage: `url(${projectImage})`}}>
            <div className="desktop-my-work-item">
                <div className="desktop-my-work-item-info">
                    <div className="desktop-my-work-item-info-heading">{projectName}</div>
                    <p className="desktop-my-work-item-info-txt">{projectDescription}</p>

                    {projectCTAs.map((cta, index) => (
                        <a
                            key={`HomeDesktopWorkItem-${projectName}-cta-${index}`}
                            className="desktop-my-work-item-info-btn my-work-item-inner-link"
                            href={cta.link}
                            target="_blank" rel="noopener noreferrer"
                        >
                            {cta.text}
                        </a>
                    ))}
                </div>
            </div>
        </div>
    )
}
